//! OpenAI API client generated by [o3gen](https://github.com/dineshdb/o3gen).
//!
//! Provides typed request/response structs and an [`OpenAIApi`] trait with a
//! default [`OpenAIApiClient`] implementation backed by `reqwest`.
//!
//! # Quick start
//!
//! ```no_run
//! use o3gen_openai::{OpenAIApi, OpenAIApiClient};
//! use o3gen_openai::types::*;
//!
//! # #[tokio::main]
//! # async fn main() -> Result<(), o3gen_openai::ApiError> {
//! let client = OpenAIApiClient::new("https://api.openai.com/v1".into());
//!
//! let body = ChatCompletionRequest::builder()
//!     .model("gpt-4o".to_string())
//!     .messages(vec![
//!         ChatCompletionRequestUserMessage::builder()
//!             .role(ChatCompletionRequestUserMessageRole::User)
//!             .content(ChatCompletionRequestUserMessageContent::String(
//!                 "Hello!".into(),
//!             ))
//!             .build()
//!             .into(),
//!     ])
//!     .build()?;
//!
//! let resp = OpenAIApi::create_chat_completion(&client, body).await?;
//! println!("{}", resp.choices[0].message.content.as_deref().unwrap_or_default());
//! # Ok(())
//! # }
//! ```
//!
//! # Streaming
//!
//! `OpenAIApiClient` also provides built-in SSE streaming for chat completions:
//!
//! # Structured extraction
//!
//! [`json()`](OpenAIApiClient::json) calls the chat completion endpoint, automatically
//! prepends a system message with the JSON schema of `T`, and deserializes the response:
//!
//! ```no_run
//! use schemars::JsonSchema;
//! use serde::Deserialize;
//! use o3gen_openai::OpenAIApiClient;
//! use o3gen_openai::types::*;
//!
//! #[derive(Deserialize, JsonSchema)]
//! struct Person {
//!     name: String,
//!     age: u8,
//!     city: String,
//! }
//!
//! # #[tokio::main]
//! # async fn main() -> Result<(), o3gen_openai::ApiError> {
//! let client = OpenAIApiClient::new("https://api.openai.com/v1".into())
//!     .with_api_key("sk-...".into());
//!
//! let body = ChatCompletionRequest::builder()
//!     .model("gpt-4o".to_string())
//!     .messages(vec![
//!         ChatCompletionRequestUserMessage::builder()
//!             .role(ChatCompletionRequestUserMessageRole::User)
//!             .content(ChatCompletionRequestUserMessageContent::String(
//!                 "John is 30 and lives in NYC".into(),
//!             ))
//!             .build()
//!             .into(),
//!     ])
//!     .build()?;
//!
//! let person: Person = client.json(body).await?;
//! println!("{} ({} from {})", person.name, person.age, person.city);
//! # Ok(())
//! # }
//! ```
//!
//! ```no_run
//! use o3gen_openai::OpenAIApiClient;
//! use o3gen_openai::types::*;
//! use futures_util::StreamExt;
//!
//! # #[tokio::main]
//! # async fn main() -> Result<(), o3gen_openai::ApiError> {
//! let client = OpenAIApiClient::new("https://api.openai.com/v1".into())
//!     .with_api_key("sk-...".into());
//!
//! let body = ChatCompletionRequest::builder()
//!     .model("gpt-4o".to_string())
//!     .messages(vec![
//!         ChatCompletionRequestUserMessage::builder()
//!             .role(ChatCompletionRequestUserMessageRole::User)
//!             .content(ChatCompletionRequestUserMessageContent::String(
//!                 "Hello!".into(),
//!             ))
//!             .build()
//!             .into(),
//!     ])
//!     .build()?;
//!
//! let mut stream = client.stream_chat(body).await?;
//! while let Some(chunk) = stream.next().await {
//!     let chunk = chunk?;
//!     for choice in &chunk.choices {
//!         if let Some(content) = &choice.delta.content {
//!             print!("{content}");
//!         }
//!     }
//! }
//! # Ok(())
//! # }
//! ```

use eventsource_stream::Eventsource;
use futures_util::StreamExt;
use futures_util::stream::BoxStream;
use serde_json::Value;

include!(concat!(env!("OUT_DIR"), "/openai.rs"));

/// Extract the provider's mid-stream failure from an SSE chunk's `error`
/// payload. The `code`, when present, feeds retry classification — a 429
/// mid-stream should hit the rate-limit budget, not kill the run.
fn stream_error_from(payload: &Value) -> ApiError {
    match payload {
        Value::String(message) => ApiError::Stream {
            message: message.clone(),
            code: None,
        },
        obj => ApiError::Stream {
            message: obj
                .get("message")
                .and_then(Value::as_str)
                .map_or_else(|| obj.to_string(), str::to_owned),
            code: obj.get("code").and_then(error_code),
        },
    }
}

/// Error codes arrive as numbers (`429`) or strings (`"429"`), depending on
/// the gateway.
fn error_code(value: &Value) -> Option<u16> {
    match value {
        Value::Number(n) => n.as_u64().and_then(|c| u16::try_from(c).ok()),
        Value::String(s) => s.parse().ok(),
        _ => None,
    }
}

fn finish_reason_is_error(value: &Value) -> bool {
    value
        .get("choices")
        .and_then(|choices| choices.get(0))
        .and_then(|choice| choice.get("finish_reason"))
        .and_then(Value::as_str)
        == Some("error")
}

impl OpenAIApiClient {
    /// Stream chat completion chunks via SSE (stream=true).
    ///
    /// Injects `"stream": true` into the request and parses the SSE response
    /// into [`CreateChatCompletionStreamResponse`] chunks. The `[DONE]` signal
    /// is filtered out automatically.
    #[allow(clippy::type_repetition_in_bounds)]
    pub async fn stream_chat(
        &self,
        request: ChatCompletionRequest,
    ) -> Result<BoxStream<'static, Result<CreateChatCompletionStreamResponse>>> {
        let url = format!("{}/chat/completions", self.base_url);

        let mut body = serde_json::to_value(&request).map_err(ApiError::Serde)?;
        if let Some(obj) = body.as_object_mut() {
            obj.insert("stream".to_string(), serde_json::Value::Bool(true));
        }

        // Retry transient connection failures (a busy local server can refuse
        // connections under bursty concurrency). Only connect-level errors are
        // retried; once the stream is established mid-stream errors are not.
        let mut retries = 0u32;
        let resp = loop {
            let mut req = self.client.post(&url).json(&body);
            if let Some(key) = &self.api_key {
                req = req.header("Authorization", &format!("Bearer {key}"));
            }
            match req.send().await {
                Ok(r) => break r,
                Err(e) if e.is_connect() && retries < 2 => {
                    retries += 1;
                    tokio::time::sleep(std::time::Duration::from_millis(u64::from(retries) * 25))
                        .await;
                    continue;
                }
                Err(e) => return Err(ApiError::Reqwest(e)),
            }
        };

        let status = resp.status();
        if !status.is_success() {
            let body_text = resp.text().await.unwrap_or_default();
            return Err(ApiError::Status {
                status,
                body: body_text,
            });
        }

        let stream = resp.bytes_stream().eventsource();

        let mapped = stream
            .map(|event| {
                let event = match event {
                    Ok(event) => event,
                    // Transport failures (dropped/truncated bodies, timeouts) keep
                    // the reqwest error so callers can classify and retry them.
                    Err(eventsource_stream::EventStreamError::Transport(e)) => {
                        return Err(ApiError::Reqwest(e));
                    }
                    Err(e) => return Err(ApiError::Builder(format!("SSE parse error: {e}"))),
                };
                if event.data == "[DONE]" {
                    return Ok(None);
                }
                // OpenRouter (and similar gateways) commit 200 and report
                // later failures as a chunk: a top-level `error` payload, or
                // a choice whose `finish_reason` is `"error"` — a variant the
                // typed enum cannot represent. Surface the provider's message
                // instead of dying as a serde error.
                let value: Value = serde_json::from_str(&event.data)?;
                if let Some(payload) = value.get("error") {
                    return Err(stream_error_from(payload));
                }
                if finish_reason_is_error(&value) {
                    return Err(ApiError::Stream {
                        message: "provider reported an error mid-stream (finish_reason: error)"
                            .into(),
                        code: None,
                    });
                }
                let chunk: CreateChatCompletionStreamResponse = serde_json::from_value(value)?;
                Ok(Some(chunk))
            })
            .filter_map(|res| async {
                match res {
                    Ok(Some(chunk)) => Some(Ok(chunk)),
                    Ok(None) => None,
                    Err(e) => Some(Err(e)),
                }
            });

        Ok(mapped.boxed())
    }

    /// Send a chat completion with a given JSON schema and return the parsed [`Value`].
    ///
    /// Prepends a system message instructing the model to respond in the schema format.
    /// Useful for dynamic/untyped scenarios where the schema is not known at compile time.
    /// Returns [`ApiError::Builder`] if the response has no content.
    pub async fn get_json(
        &self,
        mut request: ChatCompletionRequest,
        schema: &Value,
    ) -> Result<Value> {
        let schema_json = serde_json::to_string_pretty(schema).map_err(ApiError::Serde)?;

        let system_msg = ChatCompletionRequestSystemMessage::builder()
            .content(format!(
                "You must respond with ONLY valid JSON. \
                 Do NOT wrap the JSON in markdown code blocks or any other formatting.\n\
                 Schema:\n{schema_json}"
            ))
            .role(ChatCompletionRequestSystemMessageRole::System)
            .build();

        request.messages.insert(0, system_msg.into());

        let resp = self.create_chat_completion(request).await?;
        let content = resp
            .choices
            .into_iter()
            .next()
            .and_then(|c| c.message.content)
            .ok_or_else(|| ApiError::Builder("No content in response".to_string()))?;
        serde_json::from_str(&content).map_err(ApiError::Serde)
    }

    /// Call [`json_value`](Self::json_value) with the schema derived from `T`'s
    /// [`JsonSchema`](schemars::JsonSchema) impl, then deserialize into `T`.
    pub async fn json<T>(&self, request: ChatCompletionRequest) -> Result<T>
    where
        T: serde::de::DeserializeOwned + schemars::JsonSchema,
    {
        let schema = schemars::schema_for!(T);
        let schema_value = serde_json::to_value(&schema).map_err(ApiError::Serde)?;
        let value = self.get_json(request, &schema_value).await?;
        serde_json::from_value(value).map_err(ApiError::Serde)
    }
}

